bool InitImageData(PP_ImageDataFormat format, int width, int height, bool init_to_zero) {
    // Validate the image format.
    if (format < PP_IMAGEDATAFORMAT_BGRA || format > PP_IMAGEDATAFORMAT_RGBA_PREMUL) {
        return false;
    }

    // Validate width and height.
    if (width <= 0 || height <= 0) {
        return false;
    }

    // Ensure width and height do not overflow when multiplied.
    if (width > INT_MAX / height) {
        return false;
    }

